/**
 * EnergyPlus input model: an epJSON-shaped object store that serialises to IDF text
 * (what the engine runs) and to epJSON (for export), using the field order and value
 * constraints of the bundled engine's own schema (window.EP_SCHEMA, generated by
 * scripts/gen-ep-schema.mjs). No DOM access, so it runs in Node tests.
 */

class IdfModel {
  constructor(schema) {
    this.schema = schema || (typeof window !== 'undefined' ? window.EP_SCHEMA : null);
    if (!this.schema) throw new Error('EnergyPlus schema (EP_SCHEMA) is not loaded');
    this.objects = new Map(); // type -> Map(name -> fields)
    this.order = [];          // [type, name] insertion order for stable output
    this._anon = 0;
  }

  /** Add an object. `fields` uses epJSON keys; extensible groups go in fields[extName] as an array of objects. */
  add(type, name, fields = {}) {
    const def = this.schema.objects[type];
    if (!def) throw new Error(`BIM2BEM does not write ${type} objects (not in the schema subset)`);
    const key = def.named ? String(name) : (name || `${type}#${++this._anon}`);
    if (def.named) {
      if (!name) throw new Error(`${type} needs a name`);
      if (/[,;!]/.test(key)) throw new Error(`${type} name "${key}" contains a character IDF cannot hold (, ; !)`);
    }
    // Vertex lists: [[x, y, z], ...] → the object's extensible group or its fixed vertex_N fields.
    if (Array.isArray(fields.vertices) && Array.isArray(fields.vertices[0])) {
      const pts = fields.vertices;
      fields = { ...fields };
      delete fields.vertices;
      if (def.extName === 'vertices') {
        fields.vertices = pts.map(([x, y, z]) => ({ vertex_x_coordinate: x, vertex_y_coordinate: y, vertex_z_coordinate: z }));
      } else {
        pts.forEach(([x, y, z], i) => {
          fields[`vertex_${i + 1}_x_coordinate`] = x;
          fields[`vertex_${i + 1}_y_coordinate`] = y;
          fields[`vertex_${i + 1}_z_coordinate`] = z;
        });
      }
      if (def.fields.some(([f]) => f === 'number_of_vertices')) fields.number_of_vertices = pts.length;
    }
    if (!this.objects.has(type)) this.objects.set(type, new Map());
    const bucket = this.objects.get(type);
    if (bucket.has(key)) throw new Error(`Duplicate ${type} "${key}"`);
    bucket.set(key, fields);
    this.order.push([type, key]);
    return key;
  }

  has(type, name) {
    return !!(this.objects.get(type) && this.objects.get(type).has(name));
  }

  get(type, name) {
    return this.objects.get(type) ? this.objects.get(type).get(name) : undefined;
  }

  count(type) {
    return this.objects.get(type) ? this.objects.get(type).size : 0;
  }

  names(type) {
    return this.objects.get(type) ? [...this.objects.get(type).keys()] : [];
  }

  /** Check every object against the schema subset. Returns [{ severity, type, name, field, message }]. */
  validate() {
    const issues = [];
    const push = (severity, type, name, field, message) => issues.push({ severity, type, name, field, message });
    const checkValue = (type, name, field, spec, v) => {
      if (v == null || v === '') return;
      if (typeof v === 'string' && /^(autosize|autocalculate)$/i.test(v)) return;
      const types = spec.t ? [].concat(spec.t) : [];
      if (typeof v === 'number') {
        if (!Number.isFinite(v)) { push('error', type, name, field, `is not a finite number (${v})`); return; }
        if (types.length && !types.includes('number') && !types.includes('integer')) push('error', type, name, field, `expects text, got a number (${v})`);
        if (spec.minimum != null && v < spec.minimum) push('error', type, name, field, `${v} is below the minimum ${spec.minimum}`);
        if (spec.maximum != null && v > spec.maximum) push('error', type, name, field, `${v} is above the maximum ${spec.maximum}`);
        if (spec.exclusiveMinimum != null && v <= spec.exclusiveMinimum) push('error', type, name, field, `${v} must be greater than ${spec.exclusiveMinimum}`);
        if (spec.exclusiveMaximum != null && v >= spec.exclusiveMaximum) push('error', type, name, field, `${v} must be less than ${spec.exclusiveMaximum}`);
      } else if (spec.e && spec.e.length && !spec.e.some(x => String(x).toLowerCase() === String(v).toLowerCase())) {
        push('error', type, name, field, `"${v}" is not one of ${spec.e.slice(0, 8).join(', ')}${spec.e.length > 8 ? ', …' : ''}`);
      }
    };
    this.objects.forEach((bucket, type) => {
      const def = this.schema.objects[type];
      const specs = new Map(def.fields);
      if (def.unique && bucket.size > 1) push('error', type, null, null, `only one ${type} object is allowed`);
      bucket.forEach((fields, name) => {
        def.required.forEach(r => { if (fields[r] == null || fields[r] === '') push('error', type, name, r, 'is required'); });
        Object.keys(fields).forEach(k => {
          if (k === def.extName) return;
          if (!specs.has(k)) { push('error', type, name, k, 'is not a field of this object'); return; }
          checkValue(type, name, k, specs.get(k), fields[k]);
        });
        if (def.extName && fields[def.extName]) {
          const extSpecs = new Map(def.ext);
          fields[def.extName].forEach((group, gi) => Object.keys(group).forEach(k => {
            if (!extSpecs.has(k)) push('error', type, name, `${def.extName}[${gi}].${k}`, 'is not a field of this object');
            else checkValue(type, name, `${def.extName}[${gi}].${k}`, extSpecs.get(k), group[k]);
          }));
        }
      });
    });
    return issues;
  }

  /** IDF text in the engine's field order. */
  toIDF(header = []) {
    const lines = [];
    header.forEach(h => lines.push(`! ${h}`));
    if (header.length) lines.push('');
    const fmt = (v) => {
      if (v == null) return '';
      if (typeof v === 'number') {
        if (!Number.isFinite(v)) throw new Error(`Non-finite number in IDF output: ${v}`);
        return Number.isInteger(v) ? String(v) : String(Math.round(v * 1e6) / 1e6);
      }
      return String(v);
    };
    for (const [type, name] of this.order) {
      const def = this.schema.objects[type];
      const fields = this.get(type, name);
      const vals = def.fields.map(([f]) => (f === 'name' ? (def.named ? name : '') : fields[f]));
      const labels = def.fields.map(([f]) => f);
      if (def.extName && fields[def.extName]) {
        fields[def.extName].forEach(group => def.ext.forEach(([f]) => { vals.push(group[f]); labels.push(f); }));
      }
      // Trim trailing empty fields, but keep at least min_fields.
      let last = vals.length - 1;
      while (last > 0 && (vals[last] == null || vals[last] === '') && last + 1 > (def.minFields || 0)) last--;
      // A named object with only its name must still be written.
      const shown = vals.slice(0, Math.max(1, last + 1)).map(fmt);
      if (!def.named && def.fields[0] && def.fields[0][0] === 'name') shown[0] = fmt(fields.name);
      lines.push(`${type},`);
      shown.forEach((v, i) => {
        const end = i === shown.length - 1 ? ';' : ',';
        lines.push(`    ${(v + end).padEnd(28)} !- ${labels[i]}`);
      });
      lines.push('');
    }
    return lines.join('\n');
  }

  /** epJSON document (object keys are names; unnamed singletons use the type as key, as EnergyPlus does). */
  toEpJSON() {
    const out = {};
    for (const [type, name] of this.order) {
      const def = this.schema.objects[type];
      if (!out[type]) out[type] = {};
      const fields = { ...this.get(type, name) };
      Object.keys(fields).forEach(k => { if (fields[k] == null || fields[k] === '') delete fields[k]; });
      const key = def.named ? name : (Object.keys(out[type]).length ? `${type} ${Object.keys(out[type]).length + 1}` : `${type} 1`);
      out[type][key] = fields;
    }
    return out;
  }
}

/** Make a string safe and unique as an EnergyPlus object name. */
function makeNamer() {
  const used = new Set();
  return (raw, fallback = 'Object') => {
    let base = String(raw || fallback).replace(/[,;!\n\r\t]/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 90) || fallback;
    let n = base;
    let i = 2;
    while (used.has(n.toLowerCase())) n = `${base} ${i++}`;
    used.add(n.toLowerCase());
    return n;
  };
}

Object.assign(window, { IdfModel, makeNamer });
